import { useEffect, useRef, useState } from "react";
import { useCalm } from "../motion";
import "./demo-strip.css";
import { DEMO_SHOPS, THUMB_H, THUMB_W } from "./demoShops";

/** S21: "See shops made with LaunchWitness": a row of phone-shaped cards, one per demo shop.
 *
 * It is a normal horizontal scroller (swipe, drag with a trackpad, scroll-snap, arrow buttons, Tab through the links).
 * While nobody is touching it, it drifts slowly to the left like a marquee: the row's scroll position moves (composited,
 * no layout or paint of the cards), the list is drawn twice so it loops without a jump, and the copy is hidden from
 * screen readers and the keyboard. The drift stops while the pointer is over it, while anything in it has focus, for a
 * few seconds after a touch / wheel / arrow, while it is off screen or the tab is hidden, and never starts with
 * reduced motion (then it is just the scrollable row). */
const SPEED = 22; // px per second
const RESUME_MS = 3500;

export function DemoStrip() {
  const calm = useCalm();
  const row = useRef<HTMLDivElement>(null);
  const [auto, setAuto] = useState(!calm);
  const hold = useRef({ hover: false, focus: false, until: 0 });

  useEffect(() => {
    setAuto(!calm);
  }, [calm]);

  useEffect(() => {
    const el = row.current;
    if (!el || !auto) return;
    let raf = 0;
    let last = 0;
    let carry = 0;
    const tick = (t: number) => {
      raf = requestAnimationFrame(tick);
      const dt = last ? Math.min(t - last, 64) : 0;
      last = t;
      const h = hold.current;
      if (h.hover || h.focus || document.hidden || Date.now() < h.until) {
        el.classList.remove("drifting");
        return;
      }
      el.classList.add("drifting");
      carry += (SPEED * dt) / 1000;
      const step = Math.floor(carry);
      if (!step) return;
      carry -= step;
      const half = el.scrollWidth / 2;
      el.scrollLeft = el.scrollLeft + step >= half ? el.scrollLeft + step - half : el.scrollLeft + step;
    };
    // The frame loop runs ONLY while the strip is on screen: off screen it costs nothing (the hero stays as fast as before).
    const start = () => {
      if (!raf) {
        last = 0;
        raf = requestAnimationFrame(tick);
      }
    };
    const stop = () => {
      cancelAnimationFrame(raf);
      raf = 0;
      el.classList.remove("drifting");
    };
    const io = new IntersectionObserver(([e]) => (e.isIntersecting ? start() : stop()));
    io.observe(el);
    return () => {
      stop();
      io.disconnect();
    };
  }, [auto]);

  const pause = () => {
    hold.current.until = Date.now() + RESUME_MS;
  };
  const by = (dir: number) => {
    const el = row.current;
    if (!el) return;
    pause();
    const card = el.querySelector<HTMLElement>(".demo-card");
    el.scrollBy({ left: dir * (card ? card.offsetWidth + 16 : 240) * 2, behavior: calm ? "auto" : "smooth" });
  };

/** S21: the demo shops on the landing strip. Same names and order as DEMOS in backend/app/sites/demo.py (a backend
 * test checks the slugs, names, looks and that each thumbnail exists and is small). Thumbnails are made by
 * scripts/make_demo_thumbs.js from the real demo pages. */
export type DemoShop = { slug: string; name: string; look: string; thumb: string };

export const DEMO_SHOPS: DemoShop[] = [
  { slug: "meera", name: "Meera's Eggless Bakes", look: "Bakery", thumb: "/demos/meera.webp" },
  { slug: "imran", name: "Sheikh Ladies & Gents Tailors", look: "Tailoring", thumb: "/demos/imran.webp" },
  { slug: "sunita", name: "Annapurna Ghar Ka Khana", look: "Home kitchen", thumb: "/demos/sunita.webp" },
  { slug: "sugarcrumb", name: "Sugar & Crumb Cake Studio", look: "Bakery", thumb: "/demos/sugarcrumb.webp" },
  { slug: "zari", name: "Zari & Thread Tailoring", look: "Tailoring", thumb: "/demos/zari.webp" },
  { slug: "ember", name: "Ember & Clay Candles", look: "Handmade", thumb: "/demos/ember.webp" },
  { slug: "giftgarden", name: "Gift Garden Hampers", look: "Gifts", thumb: "/demos/giftgarden.webp" },
  { slug: "greencorner", name: "Green Corner Nursery", look: "General", thumb: "/demos/greencorner.webp" },
];

/** Thumbnail size (the files are 390 x 780, the first screen of each demo on a phone). */
export const THUMB_W = 390;
export const THUMB_H = 780;
// S21: thumbnails for the landing page's demo strip. Opens each demo shop (the list in
// frontend/src/landing/demoShops.ts) at 390 x 780 like a phone, with reduced motion so nothing is mid-animation,
// screenshots the first screen and saves it as WebP (<= 60 KB) in frontend/public/demos/<slug>.webp.
//
//   cd e2e && node ../scripts/make_demo_thumbs.js [base_url]        (default http://localhost:8000)
//
// Run it after any change to the shops' look, so the cards show the real pages. Uses the pre-installed Playwright
// (or LW_CHROME=<path> for a full Chrome). The WebP is encoded by the browser itself (canvas), so nothing else is needed.
const fs = require("fs");
const path = require("path");
const { chromium } = require("playwright");

const ROOT = path.resolve(__dirname, "..");
const BASE = (process.argv[2] || "http://localhost:8000").replace(/\/$/, "");
const OUT = path.join(ROOT, "frontend", "public", "demos");
const LIMIT = 60 * 1024;
const W = 390, H = 780;

const slugs = [...fs.readFileSync(path.join(ROOT, "frontend", "src", "landing", "demoShops.ts"), "utf8")
  .matchAll(/slug: "([a-z]+)"/g)].map((m) => m[1]);

(async () => {
  const browser = await chromium.launch(process.env.LW_CHROME ? { executablePath: process.env.LW_CHROME } : {});
  const ctx = await browser.newContext({ viewport: { width: W, height: H }, deviceScaleFactor: 1, reducedMotion: "reduce" });
  const page = await ctx.newPage();
  const enc = await ctx.newPage();
  fs.mkdirSync(OUT, { recursive: true });
  for (const slug of slugs) {
    const r = await page.goto(`${BASE}/demo/${slug}`, { waitUntil: "networkidle" });
    if (!r || r.status() !== 200) throw new Error(`${slug}: HTTP ${r && r.status()}`);
    await page.evaluate(() => document.fonts.ready);
    const png = await page.screenshot({ type: "png" });
    let q = 0.8, data = null;
    for (; q >= 0.3; q -= 0.1) {
      data = await enc.evaluate(async ({ src, q, w, h }) => {
        const img = new Image();
        img.src = src;
        await img.decode();
        const c = document.createElement("canvas");
        c.width = w; c.height = h;
        c.getContext("2d").drawImage(img, 0, 0);
        return c.toDataURL("image/webp", q);
      }, { src: "data:image/png;base64," + png.toString("base64"), q, w: W, h: H });
      if (!data.startsWith("data:image/webp")) throw new Error("this browser can't encode WebP");
      if (Buffer.from(data.split(",")[1], "base64").length <= LIMIT) break;
    }
    const buf = Buffer.from(data.split(",")[1], "base64");
    if (buf.length > LIMIT) throw new Error(`${slug}: still ${buf.length} bytes at the lowest quality`);
    fs.writeFileSync(path.join(OUT, `${slug}.webp`), buf);
    console.log(`${slug}.webp  ${(buf.length / 1024).toFixed(1)} KB  (quality ${q.toFixed(1)})`);
  }
  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });

