const { chromium } = require("playwright");
const OUT = process.argv[2];
(async () => {
  const b = await chromium.launch(process.env.LW_CHROME ? { executablePath: process.env.LW_CHROME } : {});
  const errs = [];
  const watch = (p, tag) => { p.on("console", m => { if (m.type() === "error" || /Content Security Policy|Refused to/i.test(m.text())) errs.push(tag + ": " + m.text()); }); p.on("pageerror", e => errs.push(tag + ": " + e)); };
  for (const w of [390, 1440]) {
    const ctx = await b.newContext({ viewport: { width: w, height: w < 600 ? 844 : 900 }, deviceScaleFactor: 2 });
    const p = await ctx.newPage(); watch(p, `landing${w}`);
    await p.goto("https://launchwitness.com/", { waitUntil: "networkidle" });
    const strip = p.locator("#demos"); await strip.scrollIntoViewIfNeeded(); await p.waitForTimeout(2500);
    const imgs = await strip.locator("img").evaluateAll(es => es.slice(0, 3).map(e => [e.currentSrc.split("/").pop(), e.naturalWidth]));
    console.log(w, "strip imgs", JSON.stringify(imgs));
    await strip.screenshot({ path: `${OUT}/live-landing-strip-${w}.png` });
    if (w === 1440) {
      const hrefs = await strip.locator('a.demo-card:not([tabindex="-1"])').evaluateAll(es => es.map(e => e.getAttribute("href")));
      for (const h of hrefs) {
        const d = await ctx.newPage(); watch(d, h);
        const r = await d.goto("https://launchwitness.com" + h, { waitUntil: "networkidle" });
        const html = await d.content();
        console.log(h, r.status(), html.includes("Demo shop: orders here are not real"), /upi:\/\//.test(html));
        await d.close();
      }
    }
    const s = await ctx.newPage(); watch(s, `shop${w}`);
    await s.goto("https://meeras-eggless-bakes.launchwitness.com/", { waitUntil: "networkidle" });
    await s.screenshot({ path: `${OUT}/live-shop-${w}.png` });
    // order maths on the demo (places no order): 1 x 1 kg + 2 x 1/2 kg truffle
    const d = await ctx.newPage(); watch(d, `demo${w}`);
    await d.goto("https://launchwitness.com/demo/meera", { waitUntil: "networkidle" });
    await d.getByRole("button", { name: "Add Chocolate truffle cake · 1 kg" }).click();
    await d.getByRole("button", { name: /½ kg/ }).first().click();
    await d.getByRole("button", { name: "One more Chocolate truffle cake · ½ kg" }).click();
    const total = await d.locator(".basket, #basket").first().innerText();
    console.log(w, "basket:", total.replace(/\s+/g, " ").slice(0, 200));
    await d.screenshot({ path: `${OUT}/live-demo-basket-${w}.png` });
    await ctx.close();
  }
